import{_ as t,o,c as n,a2 as a}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Research 0001 — Sovereign Edge: concept, positioning, and connector architecture","description":"","frontmatter":{},"headers":[],"relativePath":"sovereign-edge/research/0001-concept-and-connector-architecture.md","filePath":"sovereign-edge/research/0001-concept-and-connector-architecture.md"}'),i={name:"sovereign-edge/research/0001-concept-and-connector-architecture.md"};function r(s,e,l,c,d,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="research-0001-—-sovereign-edge-concept-positioning-and-connector-architecture" tabindex="-1">Research 0001 — Sovereign Edge: concept, positioning, and connector architecture <a class="header-anchor" href="#research-0001-—-sovereign-edge-concept-positioning-and-connector-architecture" aria-label="Permalink to &quot;Research 0001 — Sovereign Edge: concept, positioning, and connector architecture&quot;">​</a></h1><p><strong>Status:</strong> Decided<br><strong>Date:</strong> July 2026<br><strong>Author:</strong> Claude Code (session with the developer)<br><strong>Scope:</strong> Whole project — positioning, inference engine, client framework, the agent/connector (plugin) architecture, monetization model, phasing<br><strong>Related:</strong> none yet — first research doc for this repo. See root <a href="./../../CONCEPT.html">CONCEPT.md</a> for the resulting design and <a href="./../../ROADMAP.html">ROADMAP.md</a> for the phased task index.</p><hr><h2 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to &quot;Question&quot;">​</a></h2><p>Should the <code>sovereignfs</code> ecosystem build a privacy-first, fully offline on-device AI companion app (working name &quot;Sovereign Edge&quot;) as an alternative to Google&#39;s AI Edge Gallery and the third-party OGAM (Off-Grid AI Mobile) project — and if so, what positioning, technical architecture, and phased rollout let it start as a minimal MVP while evolving into an open, third-party-extensible connector ecosystem without requiring a rework later?</p><p>This is a <strong>new, standalone product</strong> in the <code>sovereignfs</code> ecosystem — unrelated to the already-planned <code>sovereign-mobile</code> (a Capacitor shell that loads a user&#39;s self-hosted <code>sovereign</code> instance in a WebView). Sovereign Edge has no runtime dependency on <code>sovereign</code> and works with zero knowledge that <code>sovereign</code> exists.</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><h3 id="competitive-landscape" tabindex="-1">Competitive landscape <a class="header-anchor" href="#competitive-landscape" aria-label="Permalink to &quot;Competitive landscape&quot;">​</a></h3><ul><li><strong>Google AI Edge Gallery</strong> — a Google tech demo for on-device model inference. Its &quot;on-device, private&quot; claim requires trusting Google&#39;s closed pipeline; nothing about it is independently verifiable, which is a non-starter for a genuinely privacy-conscious user.</li><li><strong>OGAM (Off-Grid AI Mobile)</strong> — <a href="https://ited.edu.kg/off-grid-ai/OGAM" target="_blank" rel="noreferrer">https://ited.edu.kg/off-grid-ai/OGAM</a>. Does on-device GGUF inference (Qwen 3, Llama 3.2, Gemma 3, Phi-4), image generation (Stable Diffusion), vision, Whisper speech-to-text, and function-calling/tool-use. Not fully open — a freemium app (Pro tier: $69 lifetime / $49/yr) that gates &quot;agentic&quot; actions (Calendar, email, and MCP servers such as Linear/Notion/GitHub) behind payment and behind <strong>cloud</strong> MCP servers, which undercuts its own &quot;off-grid&quot; framing. Android + iOS + macOS-via-iPad-compatibility only; no native Windows/Linux desktop story. The developer&#39;s own trial hit a stuck model download and found the UI bulkier than needed, with features not personally relevant.</li></ul><h3 id="prior-art-for-the-technical-stack" tabindex="-1">Prior art for the technical stack <a class="header-anchor" href="#prior-art-for-the-technical-stack" aria-label="Permalink to &quot;Prior art for the technical stack&quot;">​</a></h3><ul><li><strong>PocketPal AI</strong> — open source, React Native + <code>llama.rn</code> (a maintained RN binding for <code>llama.cpp</code>). Validates RN as a lean, proven stack for on-device GGUF chat apps, minus any agentic layer. Closest reference for &quot;not bulky.&quot;</li><li><strong><code>sovereign-os</code> ADR-0004</strong> (confluence/entities/sovereign-os.md) already commits, independently, to &quot;a provider-neutral local AI assistant plus opt-in web search via a self-hosted SearXNG instance — no cloud LLM dependency by default.&quot; This validates defaulting Sovereign Edge&#39;s search connector to a SearXNG-style, user-configurable meta-search endpoint rather than hardcoding one company&#39;s search API.</li></ul><h3 id="platform-constraints-on-a-third-party-plugin-model" tabindex="-1">Platform constraints on a third-party plugin model <a class="header-anchor" href="#platform-constraints-on-a-third-party-plugin-model" aria-label="Permalink to &quot;Platform constraints on a third-party plugin model&quot;">​</a></h3><ul><li><code>sovereign</code>&#39;s plugin system (the closest internal precedent) works because plugins are trusted Next.js code running inside a self-hosted server the operator controls, with only an ESLint-enforced import boundary (<code>docs/plugin-development.md</code> in <code>confluence/concepts/</code>).</li><li>That model does not transfer to a mobile app store binary. <strong>iOS forbids dynamically loading native code at runtime</strong> outside the reviewed app binary — arbitrary third-party &quot;plugins&quot; cannot ship native modules the way <code>sovereign</code> plugins ship server code. Letting arbitrary third-party code run inside a privacy-first AI app with device permissions is also a much larger trust problem than an ESLint rule.</li><li>Deep OS integration (Calendar, Contacts, Shortcuts/App Intents on iOS, App Actions on Android) is only reachable through first-party native modules reviewed on the app&#39;s own release cycle — there is no sanctioned way today for a third party to drop in that kind of native capability.</li></ul><h2 id="options-considered" tabindex="-1">Options considered <a class="header-anchor" href="#options-considered" aria-label="Permalink to &quot;Options considered&quot;">​</a></h2><h3 id="a-sovereign-style-plugin-model-arbitrary-code-same-trust-level-as-sovereign" tabindex="-1">A. Sovereign-style plugin model (arbitrary code, same trust level as <code>sovereign</code>) <a class="header-anchor" href="#a-sovereign-style-plugin-model-arbitrary-code-same-trust-level-as-sovereign" aria-label="Permalink to &quot;A. Sovereign-style plugin model (arbitrary code, same trust level as `sovereign`)&quot;">​</a></h3><p>Rejected. Doesn&#39;t fit iOS&#39;s no-dynamic-native-code constraint, and creates an outsized trust/security surface for an app whose entire value proposition is privacy.</p><h3 id="b-no-third-party-plugin-ecosystem-—-built-in-features-only" tabindex="-1">B. No third-party plugin ecosystem — built-in features only <a class="header-anchor" href="#b-no-third-party-plugin-ecosystem-—-built-in-features-only" aria-label="Permalink to &quot;B. No third-party plugin ecosystem — built-in features only&quot;">​</a></h3><p>Rejected. Forecloses &quot;anyone should be able to develop plugins&quot; and the paid- plugin monetization model the developer wants.</p><h3 id="c-tiered-connector-model-scoped-to-what-mobile-app-stores-actually-allow-recommended" tabindex="-1">C. Tiered connector model, scoped to what mobile app stores actually allow (recommended) <a class="header-anchor" href="#c-tiered-connector-model-scoped-to-what-mobile-app-stores-actually-allow-recommended" aria-label="Permalink to &quot;C. Tiered connector model, scoped to what mobile app stores actually allow (recommended)&quot;">​</a></h3><p>Three tiers, by how much trust each requires:</p><ol><li><strong>Tier 1 — declarative connectors.</strong> A manifest describes the tool schema the LLM sees, an endpoint (user- or author-configured), an auth method (token stored in the OS keychain, scoped per-connector), and request/response templates mapping the LLM&#39;s structured tool-call into an HTTP call and back. No executable code ships at all — same idea as OpenAI &quot;Actions&quot; or a Zapier app definition. Open to any third-party developer from day one of Phase 3, since there is no code to sandbox.</li><li><strong>Tier 2 — sandboxed transform scripts.</strong> For connectors needing logic beyond request/response templating: a small script running in a capability-restricted JS engine (no ambient filesystem/network/device access beyond what the host explicitly injects as call parameters). Same threat model as a browser extension&#39;s content script.</li><li><strong>Tier 3 — deep OS integration.</strong> Anything needing real native modules (Shortcuts/App Intents, direct Contacts/Calendar writes) ships inside the app&#39;s own binary, first-party only, reviewed on the normal release cycle. Not opened to third parties until/unless a native-plugin-loading story survives app store review — which mostly doesn&#39;t exist today.</li></ol><p>This is the option that lets &quot;anyone can build a plugin&quot; be true in practice, without ever trusting arbitrary native code on someone&#39;s phone.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to &quot;Recommendation&quot;">​</a></h2><p>Adopt Option C. Build the connector interface (manifest shape: tool schema, permission scope, request/response mapping) as the foundation from Phase 1 onward — even while only one connector exists and it ships hardcoded — so that opening it to third parties in Phase 3 is &quot;load this same shape from an external registry,&quot; not a rewrite of the tool-routing/permission core.</p><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h2><p>These were resolved directly by the developer during this brainstorm, not left as open research questions:</p><ul><li><strong>Task-handoff mechanism:</strong> direct integration, not delegate-to-native-app handoff. A connector (e.g. Sovereign Tasks) writes directly via its own stored, permissioned credentials, rather than opening another app&#39;s UI for the user to confirm inside.</li><li><strong>Sandboxing definition:</strong> the chat/model/memory layers are 100% offline by design — no network code path exists there at all. Any call to the outside world happens only through an explicitly permission-granted connector, and permission is scoped per-connector (granting the Search connector network access does not grant Sovereign Tasks connector access, and vice versa).</li><li><strong>Search connector:</strong> defaults toward a configurable meta-search endpoint (SearXNG-style — self-hosted, no single company in the loop), aligned with <code>sovereign-os</code>&#39;s independent ADR-0004 decision. Exact default endpoint/provider is an open question below.</li><li><strong>Sovereign Tasks connector:</strong> calls the user&#39;s self-hosted <code>sovereign</code> instance&#39;s task API directly over HTTPS (instance URL + API token, configured once), regardless of whether a native Sovereign app happens to be installed on the same device. This avoids fragile inter-app IPC/URL- scheme plumbing entirely, and still only ever touches infrastructure the user owns.</li><li><strong>Inference engine:</strong> <code>llama.cpp</code>/GGUF via <code>llama.rn</code>, matching PocketPal AI&#39;s proven stack.</li><li><strong>Client framework and platforms:</strong> React Native, targeting <strong>both iOS and Android from Phase 1</strong> — the native modules Tier 3 connectors eventually need are per-platform regardless of RN vs. fully-native, so RN costs nothing extra on that front.</li><li><strong>Monetization:</strong> the core app plus a baseline set of first-party connectors stay free forever. Paid connectors are sold via platform IAP on mobile (Apple/Google require their in-app purchase system for unlocking digital features — a direct-payment paywall inside the binary risks rejection), and via direct sale on desktop, where there is no app-store payment requirement, mirroring <code>sovereign</code>&#39;s own entitlement-token monetization model (RFC 0003 in the <code>sovereign</code> repo).</li><li><strong>Ecosystem relationship:</strong> fully standalone — no runtime dependency on <code>sovereign</code>, no shared codebase. May reuse Sovereign&#39;s visual identity and branding.</li><li><strong>Desktop:</strong> secondary and optional, sequenced after the mobile MVP proves the concept, not built in parallel from day one.</li><li><strong>Phasing (build a foundation once, widen without rework):</strong><ol><li><strong>Phase 1 (MVP/POC):</strong> chat layer only, plus one built-in connector (Search), both platforms.</li><li><strong>Phase 2:</strong> fully agentic layer with default connectors (adds Sovereign Tasks and connector management UI), still first-party only.</li><li><strong>Phase 3:</strong> the connector layer opens fully — SDK, plugin template, examples, public registry, in-app store, monetization rails.</li></ol></li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><strong>Desktop shell technology</strong> (Tauri vs. Electron vs. something else) — not decided; revisit once the mobile MVP has shipped.</li><li><strong>Tier 2 sandboxed-script runtime</strong> (an embedded Hermes isolate vs. QuickJS vs. WASM) — needs a spike once a real Tier 2 connector use case exists; none of the Phase 1/2 default connectors currently need more than Tier 1 request/response templating.</li><li><strong>Final product name/branding.</strong> &quot;Sovereign Edge&quot; is a working codename tied to this repo&#39;s directory name (<code>sovereign-edge</code>), not a decided consumer-facing name.</li><li><strong>Whether Tier 3 ever opens to third parties</strong>, and by what mechanism (e.g. discovering OS-level App Intents/App Actions that <em>other</em> apps expose, rather than ever loading third-party native code directly into this app).</li><li><strong>Default model catalog for the MVP</strong> — which GGUF models/quantizations to bundle or recommend (Gemma, Qwen, Phi, Llama variants) is unresolved; needs its own pass once on-device performance testing starts.</li><li><strong>Exact default search backend</strong> — a specific SearXNG instance/hosting story, or a different privacy-respecting meta-search API — not yet chosen.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>Given how much of this was already decided directly in conversation, this graduates straight into planning rather than needing an intermediate RFC stage: see <a href="./../../CONCEPT.html">CONCEPT.md</a> for the resulting product concept and <a href="./../../ROADMAP.html">ROADMAP.md</a> plus <a href="./../epics/">docs/epics/</a> for the phased task breakdown. If this project later adopts an RFC layer (mirroring <code>sovereign</code>&#39;s <code>docs/rfcs/</code>), the connector manifest schema (Tier 1&#39;s endpoint/auth/request/response shape) is the first thing that should be formalized that way, before Phase 3 implementation begins.</p>',31)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
